using ClosedXML.Excel;
using System.Text;

namespace ParaBeauregard.Desktop;

public sealed class MainForm : Form
{
    readonly Database db = new(); readonly Panel content = new(); readonly Label title = new(); readonly Color forest = Color.FromArgb(28, 67, 53); readonly Color sage = Color.FromArgb(218, 230, 216); readonly Color ivory = Color.FromArgb(250, 248, 241); readonly Color champagne = Color.FromArgb(224, 190, 125);
    List<Sale> sales = []; List<Product> products = []; Sale? editing;
    public MainForm()
    {
        Text = "Para Beauregard — Gestion des Ventes"; Width = 1420; Height = 880; MinimumSize = new Size(1100, 700); BackColor = ivory; Font = new Font("Segoe UI", 10); StartPosition = FormStartPosition.CenterScreen;
        sales = db.Sales(); products = db.Products();
        var side = new Panel { Dock = DockStyle.Left, Width = 245, BackColor = forest, Padding = new Padding(18) }; Controls.Add(side);
        var brand = new Label { Text = "PARA\nBEAUREGARD", ForeColor = Color.White, Font = new Font("Georgia", 20, FontStyle.Bold), Dock = DockStyle.Top, Height = 82, TextAlign = ContentAlignment.MiddleLeft }; side.Controls.Add(brand);
        var nav = new FlowLayoutPanel { Dock = DockStyle.Fill, FlowDirection = FlowDirection.TopDown, WrapContents = false, Padding = new Padding(0, 20, 0, 0) }; side.Controls.Add(nav);
        foreach (var item in new[] { ("⌂  Dashboard", (Action)ShowDashboard), ("＋  Nouvelle vente", (Action)(() => ShowNewSale())), ("▤  Historique ventes", (Action)ShowHistory), ("▦  Catalogue produits", (Action)ShowCatalog), ("◷  Suivi journalier", (Action)ShowDaily), ("◒  Statistiques", (Action)ShowStats), ("⇩  Sauvegardes", (Action)ShowBackups), ("⚙  Paramètres", (Action)ShowSettings) }) { var b = new Button { Text = item.Item1, Width = 207, Height = 45, FlatStyle = FlatStyle.Flat, ForeColor = Color.White, BackColor = forest, TextAlign = ContentAlignment.MiddleLeft, Font = new Font("Segoe UI", 10, FontStyle.Bold), Margin = new Padding(0, 3, 0, 3), Cursor = Cursors.Hand }; b.FlatAppearance.BorderSize = 0; b.Click += (_, _) => item.Item2(); nav.Controls.Add(b); }
        var header = new Panel { Dock = DockStyle.Top, Height = 82, BackColor = Color.White, Padding = new Padding(34, 23, 30, 0) }; Controls.Add(header); header.BringToFront(); title.Text = "Dashboard"; title.Font = new Font("Georgia", 23, FontStyle.Bold); title.ForeColor = forest; title.AutoSize = true; header.Controls.Add(title); var date = new Label { Text = DateTime.Now.ToString("dddd d MMMM yyyy"), AutoSize = true, ForeColor = Color.Gray, Anchor = AnchorStyles.Top | AnchorStyles.Right, Location = new Point(1050, 30) }; header.Controls.Add(date);
        content.Dock = DockStyle.Fill; content.Padding = new Padding(34, 28, 34, 28); Controls.Add(content); content.BringToFront(); header.BringToFront(); ShowDashboard();
    }
    void Reset(string name) { title.Text = name; content.Controls.Clear(); sales = db.Sales(); products = db.Products(); }
    Label Txt(string text, int size = 10, Color? color = null) => new() { Text = text, Font = new Font("Segoe UI", size, FontStyle.Regular), ForeColor = color ?? Color.FromArgb(45, 55, 49), AutoSize = true };
    Button ActionButton(string text, EventHandler click, Color? back = null) { var b = new Button { Text = text, AutoSize = true, Height = 38, Padding = new Padding(14, 0, 14, 0), FlatStyle = FlatStyle.Flat, BackColor = back ?? forest, ForeColor = Color.White, Font = new Font("Segoe UI", 9, FontStyle.Bold), Cursor = Cursors.Hand }; b.FlatAppearance.BorderSize = 0; b.Click += click; return b; }
    void ShowDashboard()
    {
        Reset("Dashboard"); var today = GoalEngine.Calculate(sales, db.Target, sales.Select(s => s.Date.Date).DefaultIfEmpty(DateTime.Today).Min(), DateTime.Today).Last(); var flow = Flow();
        flow.Controls.Add(Card("CA aujourd'hui", Money(today.Revenue), champagne)); flow.Controls.Add(Card("Coût aujourd'hui", Money(today.Cost), Color.FromArgb(232, 220, 199))); flow.Controls.Add(Card("Gain aujourd'hui", Money(today.Profit), sage)); flow.Controls.Add(Card("Objectif réel", Money(today.Target), forest, Color.White));
        var status = new Panel { Dock = DockStyle.Top, Height = 105, BackColor = today.Remaining == 0 ? forest : Color.FromArgb(255, 244, 220), Padding = new Padding(22), Margin = new Padding(0, 24, 0, 10) }; status.Controls.Add(Txt(today.Remaining == 0 ? "✅  OBJECTIF ATTEINT" : $"⚠  Il reste {Money(today.Remaining)} à gagner", 16, today.Remaining == 0 ? Color.White : forest)); var statusDetail = Txt($"Progression : {today.Progress:0}%   •   Retard précédent : {Money(today.PreviousDelay)}   •   Surplus : {Money(today.Surplus)}   •   {today.SalesCount} vente(s)   •   {today.Quantity:0.##} produit(s)", 10, today.Remaining == 0 ? Color.White : Color.DimGray); statusDetail.Location = new Point(24, 58); status.Controls.Add(statusDetail); content.Controls.Add(status); content.Controls.Add(flow);
        var actions = new FlowLayoutPanel { Dock = DockStyle.Top, Height = 70, Padding = new Padding(0, 20, 0, 0) }; actions.Controls.Add(ActionButton("＋ Enregistrer une vente", (_, _) => ShowNewSale())); actions.Controls.Add(ActionButton("Voir l'historique", (_, _) => ShowHistory(), Color.FromArgb(104, 132, 112))); content.Controls.Add(actions);
    }
    Panel Card(string label, string value, Color back, Color? fore = null) { var p = new Panel { Width = 245, Height = 120, BackColor = back, Margin = new Padding(0, 0, 18, 0), Padding = new Padding(18) }; p.Controls.Add(Txt(label.ToUpper(), 9, fore ?? forest)); var v = Txt(value, 23, fore ?? forest); v.Location = new Point(18, 48); v.Font = new Font("Georgia", 22, FontStyle.Bold); p.Controls.Add(v); return p; }
    FlowLayoutPanel Flow() => new() { Dock = DockStyle.Top, Height = 140, WrapContents = false, FlowDirection = FlowDirection.LeftToRight };
    static string Money(decimal n) => $"{n:N2} DH";
    TableLayoutPanel FormGrid() { var g = new TableLayoutPanel { Dock = DockStyle.Top, ColumnCount = 4, AutoSize = true, Padding = new Padding(0, 5, 0, 0) }; for (var i = 0; i < 4; i++) g.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 25)); return g; }
    TextBox Input(string placeholder = "") => new() { Width = 245, Height = 33, PlaceholderText = placeholder, BorderStyle = BorderStyle.FixedSingle };
    void ShowNewSale(Sale? sale = null)
    {
        Reset(sale is null ? "Nouvelle vente" : "Modifier la vente"); editing = sale; var g = FormGrid(); var day = new DateTimePicker { Width = 245, Format = DateTimePickerFormat.Short, Value = sale?.Date ?? DateTime.Today }; var product = new ComboBox { Width = 245, DropDownStyle = ComboBoxStyle.DropDownList }; product.Items.Add("— Saisie libre —"); foreach (var p in products) product.Items.Add($"{p.Name} | {p.Sku}"); product.SelectedIndex = 0;
        var name = Input("Nom du produit"); var brand = Input("Marque"); var cat = Input("Catégorie"); var sku = Input("SKU / référence"); var qty = Input("1"); var buy = Input("0,00"); var sell = Input("0,00"); var payment = new ComboBox { Width = 245, DropDownStyle = ComboBoxStyle.DropDownList }; payment.Items.AddRange(["Espèces", "Carte bancaire", "Virement", "Paiement mobile", "Autre"]); payment.SelectedIndex = 0; var notes = Input("Notes facultatives");
        if (sale != null) { day.Value = sale.Date; name.Text = sale.Product; brand.Text = sale.Brand; cat.Text = sale.Category; sku.Text = sale.Sku; qty.Text = sale.Quantity.ToString(); buy.Text = sale.PurchasePrice.ToString(); sell.Text = sale.SalePrice.ToString(); payment.Text = sale.Payment; notes.Text = sale.Notes; }
        product.SelectedIndexChanged += (_, _) => { if (product.SelectedIndex > 0) { var p = products[product.SelectedIndex - 1]; name.Text = p.Name; brand.Text = p.Brand; cat.Text = p.Category; sku.Text = p.Sku; buy.Text = p.PurchasePrice.ToString(); sell.Text = p.SalePrice.ToString(); } };
        foreach (var (label, control) in new (string, Control)[] { ("Date", day), ("Produit du catalogue", product), ("Nom du produit", name), ("Marque", brand), ("Catégorie", cat), ("SKU / référence", sku), ("Quantité", qty), ("Prix d'achat (DH)", buy), ("Prix de vente (DH)", sell), ("Mode de paiement", payment), ("Notes", notes) }) { var box = new Panel { Height = 75, Dock = DockStyle.Fill, Padding = new Padding(0, 0, 14, 8) }; box.Controls.Add(Txt(label, 9, Color.DimGray)); control.Location = new Point(0, 25); box.Controls.Add(control); g.Controls.Add(box); }
        content.Controls.Add(g); var preview = Txt("Gain estimé : —", 12, forest); preview.Location = new Point(0, 415); content.Controls.Add(preview); EventHandler calc = (_, _) => { if (decimal.TryParse(qty.Text, out var q) && decimal.TryParse(buy.Text, out var b) && decimal.TryParse(sell.Text, out var s)) preview.Text = $"Gain estimé : {Money(q * (s - b))}   •   Coût total : {Money(q * b)}   •   Chiffre d'affaires : {Money(q * s)}"; }; qty.TextChanged += calc; buy.TextChanged += calc; sell.TextChanged += calc;
        var save = ActionButton("Enregistrer la vente", (_, _) => { if (!decimal.TryParse(qty.Text, out var q) || !decimal.TryParse(buy.Text, out var b) || !decimal.TryParse(sell.Text, out var s) || string.IsNullOrWhiteSpace(name.Text) || q <= 0) { MessageBox.Show("Veuillez renseigner un produit et des montants valides.", "Vérification", MessageBoxButtons.OK, MessageBoxIcon.Warning); return; } db.SaveSale(new Sale(sale?.Id ?? Guid.NewGuid(), day.Value, name.Text.Trim(), brand.Text.Trim(), cat.Text.Trim(), sku.Text.Trim(), q, b, s, payment.Text, notes.Text.Trim())); ShowDashboard(); }); save.Location = new Point(0, 470); content.Controls.Add(save);
    }
    void ShowHistory()
    {
        Reset("Historique ventes"); var search = Input("Rechercher produit, marque ou SKU…"); search.Dock = DockStyle.Top; content.Controls.Add(search); var grid = Grid(["Date", "Produit", "Marque", "Catégorie", "Qté", "CA", "Gain", "Paiement"]); grid.Dock = DockStyle.Fill; content.Controls.Add(grid); void Fill() { grid.Rows.Clear(); var term = search.Text.Trim().ToLowerInvariant(); foreach (var s in sales.Where(x => string.IsNullOrEmpty(term) || $"{x.Product} {x.Brand} {x.Sku}".ToLowerInvariant().Contains(term))) { var row = grid.Rows.Add(s.Date.ToString("dd/MM/yyyy"), s.Product, s.Brand, s.Category, s.Quantity, Money(s.Revenue), Money(s.Profit), s.Payment); grid.Rows[row].Tag = s; } } search.TextChanged += (_, _) => Fill(); grid.CellDoubleClick += (_, e) => { if (e.RowIndex >= 0 && grid.Rows[e.RowIndex].Tag is Sale s) ShowNewSale(s); }; var del = ActionButton("Supprimer la vente sélectionnée", (_, _) => { if (grid.CurrentRow?.Tag is Sale s && MessageBox.Show("Supprimer cette vente ?", "Confirmation", MessageBoxButtons.YesNo) == DialogResult.Yes) { db.Delete(s.Id); ShowHistory(); } }, Color.FromArgb(150, 67, 57)); del.Dock = DockStyle.Bottom; content.Controls.Add(del); Fill(); }
    DataGridView Grid(string[] cols) { var g = new DataGridView { AutoGenerateColumns = false, AllowUserToAddRows = false, ReadOnly = true, BackgroundColor = Color.White, BorderStyle = BorderStyle.None, RowHeadersVisible = false, SelectionMode = DataGridViewSelectionMode.FullRowSelect, Dock = DockStyle.Fill, AutoSizeColumnsMode = DataGridViewAutoSizeColumnsMode.Fill }; foreach (var c in cols) g.Columns.Add(new DataGridViewTextBoxColumn { HeaderText = c }); return g; }
    void ShowCatalog()
    {
        Reset("Catalogue produits"); var grid = Grid(["Nom", "Marque", "Catégorie", "SKU", "Prix achat", "Prix vente"]); content.Controls.Add(grid); foreach (var p in products) grid.Rows.Add(p.Name, p.Brand, p.Category, p.Sku, Money(p.PurchasePrice), Money(p.SalePrice)); var add = ActionButton("＋ Ajouter un produit", (_, _) => AddProduct()); add.Dock = DockStyle.Bottom; content.Controls.Add(add);
    }
    void AddProduct() { using var f = new ProductDialog(); if (f.ShowDialog(this) == DialogResult.OK) { db.SaveProduct(new Product(Guid.NewGuid(), f.NameValue, f.Brand, f.Category, f.Sku, f.Purchase, f.Sale)); ShowCatalog(); } }
    void ShowDaily() { Reset("Suivi journalier"); var days = GoalEngine.Calculate(sales, db.Target, sales.Select(s => s.Date.Date).DefaultIfEmpty(DateTime.Today).Min(), DateTime.Today); var g = Grid(["Jour", "Ventes", "Qtés", "CA", "Coût", "Bénéfice", "Objectif", "Différence", "Report"]); content.Controls.Add(g); foreach (var d in days.AsEnumerable().Reverse()) g.Rows.Add(d.Day.ToString("dd/MM/yyyy"), d.SalesCount, d.Quantity, Money(d.Revenue), Money(d.Cost), Money(d.Profit), Money(d.Target), Money(d.Difference), Money(d.CarriedDelay)); }
    void ShowStats() { Reset("Statistiques"); var all = GoalEngine.Calculate(sales, db.Target, sales.Select(s => s.Date.Date).DefaultIfEmpty(DateTime.Today).Min(), DateTime.Today); var topProducts = sales.GroupBy(s => s.Product).OrderByDescending(g => g.Sum(x => x.Profit)).Take(5).Select(g => $"{g.Key} — {Money(g.Sum(x => x.Profit))}"); var topBrands = sales.GroupBy(s => s.Brand).OrderByDescending(g => g.Sum(x => x.Profit)).Take(5).Select(g => $"{g.Key} — {Money(g.Sum(x => x.Profit))}"); var panel = new FlowLayoutPanel { Dock = DockStyle.Fill, FlowDirection = FlowDirection.TopDown, WrapContents = false }; panel.Controls.Add(Card("Panier moyen", sales.Count == 0 ? "0,00 DH" : Money(sales.Average(s => s.Revenue)), champagne)); panel.Controls.Add(Txt($"Jours objectif atteint : {all.Count(x => x.Remaining == 0)}   •   Non atteint : {all.Count(x => x.Remaining > 0)}   •   Taux : {(all.Count == 0 ? 0 : all.Count(x => x.Remaining == 0) * 100m / all.Count):0}%", 13, forest)); panel.Controls.Add(Txt("TOP PRODUITS\n" + string.Join("\n", topProducts.DefaultIfEmpty("Aucune donnée")), 12)); panel.Controls.Add(Txt("\nTOP MARQUES\n" + string.Join("\n", topBrands.DefaultIfEmpty("Aucune donnée")), 12)); content.Controls.Add(panel); }
    void ShowBackups() { Reset("Sauvegardes"); var p = new FlowLayoutPanel { Dock = DockStyle.Top, Height = 100 }; p.Controls.Add(ActionButton("Sauvegarder maintenant", (_, _) => MessageBox.Show($"Sauvegarde créée :\n{db.Backup()}"))); p.Controls.Add(ActionButton("Restaurer une sauvegarde", (_, _) => { using var d = new OpenFileDialog { InitialDirectory = db.BackupFolder, Filter = "Base SQLite|*.db" }; if (d.ShowDialog() == DialogResult.OK) { db.Restore(d.FileName); MessageBox.Show("Sauvegarde restaurée. L'application va se fermer pour appliquer la restauration."); Application.Restart(); } }, Color.FromArgb(104, 132, 112))); p.Controls.Add(ActionButton("Exporter CSV", (_, _) => ExportCsv())); p.Controls.Add(ActionButton("Exporter XLSX", (_, _) => ExportXlsx())); content.Controls.Add(p); content.Controls.Add(Txt($"Base locale : {db.DatabasePath}\nSauvegardes automatiques : {db.BackupFolder}", 11, Color.DimGray)); }
    void ExportCsv() { using var d = new SaveFileDialog { Filter = "CSV|*.csv", FileName = $"ventes-{DateTime.Today:yyyyMMdd}.csv" }; if (d.ShowDialog() != DialogResult.OK) return; var sb = new StringBuilder("Date;Produit;Marque;Catégorie;SKU;Quantité;Prix achat;Prix vente;CA;Coût;Bénéfice;Paiement;Notes\n"); foreach (var s in sales) sb.AppendLine($"{s.Date:dd/MM/yyyy};{s.Product};{s.Brand};{s.Category};{s.Sku};{s.Quantity};{s.PurchasePrice};{s.SalePrice};{s.Revenue};{s.Cost};{s.Profit};{s.Payment};{s.Notes}"); File.WriteAllText(d.FileName, sb.ToString(), Encoding.UTF8); }
    void ExportXlsx() { using var d = new SaveFileDialog { Filter = "Excel|*.xlsx", FileName = $"ventes-{DateTime.Today:yyyyMMdd}.xlsx" }; if (d.ShowDialog() != DialogResult.OK) return; using var wb = new XLWorkbook(); var ws = wb.Worksheets.Add("Ventes"); var headers = new[] { "Date", "Produit", "Marque", "Catégorie", "SKU", "Quantité", "Prix achat", "Prix vente", "CA", "Coût", "Bénéfice", "Paiement", "Notes" }; for (var i = 0; i < headers.Length; i++) ws.Cell(1, i + 1).Value = headers[i]; for (var r = 0; r < sales.Count; r++) { var s = sales[r]; object[] row = [s.Date, s.Product, s.Brand, s.Category, s.Sku, s.Quantity, s.PurchasePrice, s.SalePrice, s.Revenue, s.Cost, s.Profit, s.Payment, s.Notes]; for (var c = 0; c < row.Length; c++) ws.Cell(r + 2, c + 1).Value = row[c]?.ToString() ?? ""; } ws.Columns().AdjustToContents(); wb.SaveAs(d.FileName); }
    void ShowSettings() { Reset("Paramètres"); var target = Input(db.Target.ToString()); var panel = new Panel { Dock = DockStyle.Top, Height = 100 }; panel.Controls.Add(Txt("Objectif minimum quotidien (DH)", 11, forest)); target.Location = new Point(0, 30); panel.Controls.Add(target); panel.Controls.Add(ActionButton("Enregistrer", (_, _) => { if (decimal.TryParse(target.Text, out var v) && v >= 0) { db.Target = v; MessageBox.Show("Objectif enregistré."); ShowDashboard(); } })); panel.Controls[2].Location = new Point(265, 27); content.Controls.Add(panel); content.Controls.Add(Txt("Les calculs de retard sont recalculés à partir de toutes les ventes enregistrées. Les jours sans vente sont conservés dans le suivi.", 11, Color.DimGray)); }
}

sealed class ProductDialog : Form
{
    public string NameValue => name.Text; public string Brand => brand.Text; public string Category => category.Text; public string Sku => sku.Text; public decimal Purchase => decimal.TryParse(purchase.Text, out var x) ? x : 0; public decimal Sale => decimal.TryParse(sale.Text, out var x) ? x : 0; readonly TextBox name = new(), brand = new(), category = new(), sku = new(), purchase = new(), sale = new();
    public ProductDialog() { Text = "Nouveau produit"; Width = 430; Height = 390; StartPosition = FormStartPosition.CenterParent; var p = new TableLayoutPanel { Dock = DockStyle.Fill, Padding = new Padding(20), RowCount = 7, ColumnCount = 2 }; p.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 35)); p.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 65)); foreach (var (l, c) in new[] { ("Nom", name), ("Marque", brand), ("Catégorie", category), ("SKU", sku), ("Prix achat", purchase), ("Prix vente", sale) }) { p.Controls.Add(new Label { Text = l, AutoSize = true }, 0, p.RowCount - 7); p.Controls.Add(c, 1, p.RowCount - 7); p.RowCount--; } var ok = new Button { Text = "Enregistrer", DialogResult = DialogResult.OK, Dock = DockStyle.Fill }; p.Controls.Add(ok, 1, 6); Controls.Add(p); AcceptButton = ok; }
}
